                        seen.add((yy, xx))
                        stack.append((yy, xx))
            objects.append((color, cells))

    # Objects are drawn toward the edge opposite their horizontal side:
    # left-side objects rise, right-side objects descend.
    out = [[0] * w for _ in range(h)]
